// A course code generated by POST /api/courses when the body has none:
// the format and the loop that skips a code typed by hand earlier — no database.
import { describe, expect, it } from 'vitest';
import { COURSE_CODE_PREFIX, COURSE_CODE_SEQUENCE_KEY, COURSE_CODE_SEQUENCE_PERIOD, formatCourseCode, generateCourseCode } from './course-code.js';
import { COURSE_CODE_PATTERN } from './courses.validation.js';

describe('formatCourseCode', () => {
  it('pads to five digits, grows past them and always matches the course code pattern', () => {
    expect(formatCourseCode(1)).toBe('CRS-00001');
    expect(formatCourseCode(42)).toBe('CRS-00042');
    expect(formatCourseCode(99999)).toBe('CRS-99999');
    expect(formatCourseCode(100000)).toBe('CRS-100000');
    expect(formatCourseCode(Number.MAX_SAFE_INTEGER)).toBe(`CRS-${Number.MAX_SAFE_INTEGER}`);
    for (const value of [1, 99999, 100000, 1234567, Number.MAX_SAFE_INTEGER]) expect(formatCourseCode(value)).toMatch(COURSE_CODE_PATTERN);
    // The frontend opens a course through its general class `<code>-GEN`; class codes stop at 32 characters.
    expect(`${formatCourseCode(Number.MAX_SAFE_INTEGER)}-GEN`.length).toBeLessThanOrEqual(32);
  });

  it('refuses a number that is not a positive safe integer', () => {
    for (const value of [0, -1, 1.5, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) expect(() => formatCourseCode(value)).toThrow(RangeError);
  });

  it('uses one counter row without a period', () => {
    expect(COURSE_CODE_PREFIX).toBe('CRS');
    expect(COURSE_CODE_SEQUENCE_KEY).toBe('course');
    expect(COURSE_CODE_SEQUENCE_PERIOD).toBe('');
  });
});

describe('generateCourseCode', () => {
  const counterFrom = (start: number) => {
    let next = start;
    const reserved: number[] = [];
    return {
      reserved,
      reserve: () => {
        reserved.push(next);
        return Promise.resolve(next++);
      },
    };
  };

  it('returns the first number when its code is free', async () => {
    const counter = counterFrom(7);
    expect(await generateCourseCode(counter.reserve, () => Promise.resolve(false))).toBe('CRS-00007');
    expect(counter.reserved).toEqual([7]);
  });

  it('skips the codes already taken, taking the next number each time', async () => {
    const counter = counterFrom(7);
    const taken = new Set(['CRS-00007', 'CRS-00008']);
    const asked: string[] = [];
    const code = await generateCourseCode(counter.reserve, (candidate) => {
      asked.push(candidate);
      return Promise.resolve(taken.has(candidate));
    });
    expect(code).toBe('CRS-00009');
    expect(asked).toEqual(['CRS-00007', 'CRS-00008', 'CRS-00009']);
    expect(counter.reserved).toEqual([7, 8, 9]);
  });

  it('passes on a failing counter or lookup (the transaction rolls back)', async () => {
    await expect(generateCourseCode(() => Promise.reject(new Error('db down')), () => Promise.resolve(false))).rejects.toThrow('db down');
    await expect(generateCourseCode(() => Promise.resolve(1), () => Promise.reject(new Error('lookup failed')))).rejects.toThrow('lookup failed');
  });
});
